// Ask the browser. It shows a permission pop-up, and only works on https or localhost.
function getLocation() {
  return new Promise((resolve, reject) => {
    navigator.geolocation.getCurrentPosition(
      (pos) => resolve({ lat: pos.coords.latitude, lon: pos.coords.longitude, name: "your location" }),
      () => reject(new Error("Location was blocked")),
    );
  });
}

// Plan B: the visitor types a city and we look it up.
async function findCity(name) {
  const url = `https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(name)}&count=1`;
  const data = await (await fetch(url)).json();
  const place = data.results?.[0]; // missing when nothing matches
  if (!place) throw new Error(`No city called ${name}`);
  return { lat: place.latitude, lon: place.longitude, name: `${place.name}, ${place.country}` };
}

async function getSky(lat, lon) {
  const url =
    `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}` +
    `&current=cloud_cover,visibility,is_day&timezone=auto`;
  const reply = await fetch(url);
  if (!reply.ok) throw new Error(`Weather replied ${reply.status}`);
  const data = await reply.json();

  return {
    clouds: data.current.cloud_cover,              // percent of sky covered
    visibilityKm: data.current.visibility / 1000,  // the reply is in metres
    isDay: data.current.is_day === 1,              // 1 for day, 0 for night
    timezone: data.timezone,                       // like "Asia/Kolkata"
  };
}

async function getTwilight(lat, lon) {
  // formatted=0 gives times in a standard format that Date understands.
  const url = `https://api.sunrise-sunset.org/json?lat=${lat}&lng=${lon}&formatted=0`;
  const { results } = await (await fetch(url)).json();
  return {
    sunset: new Date(results.sunset),
    nauticalEnd: new Date(results.nautical_twilight_end),     // evening
    nauticalBegin: new Date(results.nautical_twilight_begin), // next morning
  };
}

// Dark enough to see the ISS: Sun at least 6 degrees below the horizon.
function isDark(t, now = new Date()) {
  return now >= t.nauticalEnd || now <= t.nauticalBegin;
}

const SYNODIC = 29.530588853;                        // days from one new moon to the next
const KNOWN_NEW_MOON = Date.UTC(2000, 0, 6, 18, 14); // a new moon we know for certain

function moonPhase(date = new Date()) {
  const days = (date - KNOWN_NEW_MOON) / 86400000;   // milliseconds in a day
  const age = ((days % SYNODIC) + SYNODIC) % SYNODIC; // days since the last new moon
  const lit = (1 - Math.cos((2 * Math.PI * age) / SYNODIC)) / 2; // 0 new, 1 full

  const names = ["New moon", "Waxing crescent", "First quarter", "Waxing gibbous",
    "Full moon", "Waning gibbous", "Last quarter", "Waning crescent"];
  const name = names[Math.round((age / SYNODIC) * 8) % 8];

  return { age, percentLit: Math.round(lit * 100), name };
}

