// satellite.js turns an orbit description (a TLE) into a position.
async function loadISS() {
  const url = "https://api.wheretheiss.at/v1/satellites/25544/tles";
  const tle = await (await fetch(url)).json();
  return satellite.twoline2satrec(tle.line1, tle.line2);
}

// Where is the ISS in your sky? Angles in degrees.
function skyPosition(satrec, date, me) {
  const eci = satellite.propagate(satrec, date).position;      // km from Earth's centre
  const ecf = satellite.eciToEcf(eci, satellite.gstime(date)); // follow the Earth's spin
  const look = satellite.ecfToLookAngles(me, ecf);
  return {
    elevation: satellite.radiansToDegrees(look.elevation),
    azimuth: satellite.radiansToDegrees(look.azimuth),
  };
}

// You: radians, and height in km.
const me = {
  latitude: satellite.degreesToRadians(28.61),
  longitude: satellite.degreesToRadians(77.21),
  height: 0.2,
};

function findPasses(satrec, me, hours = 24) {
  const passes = [];
  let pass = null;
  const start = Date.now();

  for (let t = start; t < start + hours * 3600 * 1000; t += 30 * 1000) { // every 30 s
    const sky = skyPosition(satrec, new Date(t), me);
    if (sky.elevation > 0) {
      pass ??= { rise: new Date(t), maxElevation: 0 }; // it just rose above the horizon
      pass.set = new Date(t);
      pass.maxElevation = Math.max(pass.maxElevation, sky.elevation);
    } else if (pass) {
      if (pass.maxElevation >= 10) passes.push(pass); // ignore low, hidden passes
      pass = null;
    }
  }
  return passes;
}

function tonight({ clouds, percentLit, isDark }) {
  if (!isDark) return { score: 0, text: "Wait for darkness" };

  let score = 100 - clouds * 0.8;      // clouds matter most
  score -= percentLit * 0.2;           // bright moonlight washes out faint stars
  score = Math.max(0, Math.round(score));

  const text = score >= 70 ? "Great night to look up"
    : score >= 40 ? "Fair: bright things only"
    : "Poor: clouds or glare";
  return { score, text };
}

console.log(tonight({ clouds: 10, percentLit: 5, isDark: true }));  // 91, great
