// Show a moment in the viewer's chosen place, not in the server's time zone.
function showTime(date, timezone) {
  return date.toLocaleTimeString("en-GB", {
    hour: "2-digit",
    minute: "2-digit",
    timeZone: timezone, // from the weather reply, like "Asia/Kolkata"
  });
}

